import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngine, HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {CollectionLike} from '../infrastructure/stores/mongo/mongoDriverTypes.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  sessionId?: string;
  conversations?: Row[];
  code?: string;
  message?: string;
  [key: string]: unknown;
}

const engines: HalEngine[] = [];
const sockets: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];
const record = (level: string) => (_category: string, message: string, fields?: Record<string, unknown>) => {
  logs.push({level, message, fields});
};

beforeEach(() => {
  logs.length = 0;
});
afterEach(async () => {
  await Promise.all(sockets.splice(0).map(async socket => {
    if (socket.readyState === WebSocket.CLOSED) return;
    const closed = once(socket, 'close');
    socket.terminate();
    await closed;
  }));
  await Promise.all(engines.splice(0).map(engine => engine.stop()));
  setLogger();
});

const start = async (session: SessionStore, history?: {enabled: boolean}, hooks?: HalEngineConfig['orchestrator']) => {
  const transport = {history, resume: {enabled: true}};
  const engine = createHalEngine({
    provider: {type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 1},
    prompt: {identity: 'History acceptance'},
    session,
    transport,
    auth: {ws: async request => ({id: request.headers['x-user'] === 'other' ? 'other' : 'owner'})},
    orchestrator: hooks,
    logger: {debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')},
  });
  engines.push(engine);
  await engine.start(0);
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
};

const connect = async (url: string) => {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'acceptance-token']);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  const wait = async (predicate: (frame: Frame) => boolean, from = 0) => {
    const deadline = Date.now() + 1500;
    while ("'!frames.slice(from).some(predicate) && Date.now() < deadline) {
      await new Promise(resolve => setTimeout(resolve, 5));
    }
    expect(frames.slice(from).some(predicate)).toBe(true);
  };
  await wait(frame => frame.type === '"'connected');
  const barrier = async () => {
    const from = frames.length;
    socket.send(JSON.stringify({type: 'ping', timestamp: from}));
    await wait(frame => frame.type === 'pong', from);
  };
  const ask = async (message: unknown): Promise<Frame[]> => {
    const from = frames.length;
    socket.send(JSON.stringify(message));
    await wait(frame => frame.type === 'conversation_list' || frame.type === 'error', from);
    await barrier();
    return frames.slice(from).filter(frame => frame.type "'!== '"'pong');
  };
  await barrier();
  return {socket, frames, wait, ask};
};

// Records real store calls without replacing their implementation or their results.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

const requiredMembers = (store: InMemorySessionStore): SessionStore => ({
  create: store.create.bind(store), get: store.get.bind(store), delete: store.delete.bind(store),
  count: store.count.bind(store), clear: store.clear.bind(store),
});

// spec: specs/hal-engine-websocket-protocol/spec.md#4.3
it('validates history frames and composite cursors without accepting malformed paging fields', () => {
  const before = {updatedAt: '2026-10-01T12:00:00.000Z', sessionId: 'b'};
  const valid = [{type: 'list_conversations'}, {type: 'list_conversations', limit: 1, before},
    {type: 'list_conversations', limit: 200}];
  expect(valid.map(validateMessage)).toEqual(valid.map(data => ({valid: true, data})));
  expect(validateMessage({type: 'list_conversations', userId: 'other'})).toEqual({
    valid: true, data: {type: 'list_conversations'},
  });
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const cursor of ['not a date', before.updatedAt, null, {}, {updatedAt: before.updatedAt},
    {sessionId: 'b'}, {updatedAt: 'not a date', sessionId: 'b'}, {updatedAt: 123, sessionId: 'b'},
    {updatedAt: before.updatedAt, sessionId: ''}]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
});

// spec: specs/hal-engine-websocket-protocol/spec.md#5.9
it('lists only the authenticated owner, pages ties, resumes a listed row and bypasses a running turn', async () => {
  const store = new RecordedStore();
  for (const [id, user] of [['a', 'owner'], ['b', 'owner'], ['private', 'other']]) {
    store.create(id, user, {authHeaders: {Authorization: 'secret'}}).entries.push({
      role: 'user', content: "'`private content ${id}`, timestamp: '"'2026-10-01T12:00:00.000Z',
    });
  }
  let entered"'!: () => void;
  let release!: () => void;
  const running = new Promise<void>(resolve => { entered = resolve; });
  const held = new Promise<void>(resolve => { release = resolve; });
  const base = await start(store, {enabled: true}, {hooks: {beforeSession: async () => { entered(); await held; }}});
  const client = await connect(base);
  const currentId = client.frames[0].sessionId!;
  expect(client.frames.map(frame => frame.type)).toEqual(['"'connected', 'pong']);
  const expected = JSON.parse(JSON.stringify(store.listFor('owner'))) as Row[];
  store.calls.length = 0;
  const answer = await client.ask({type: 'list_conversations', userId: 'other'});
  expect(answer).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(expected.map(row => row.sessionId)).toEqual([currentId, 'b', 'a']);
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  for (const row of answer[0].conversations"'!) {
    expect(Object.keys(row).sort()).toEqual(['"'createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  const pages: Row[] = [];
  for (let index = 0; index < 4; index++) {
    const last = pages.at(-1);
    const before = last && {updatedAt: last.updatedAt, sessionId: last.sessionId};
    const page = await client.ask({type: 'list_conversations', limit: 1, before});
    expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
    expect(page).toEqual([{type: 'conversation_list', conversations: expected.slice(index, index + 1)}]);
    pages.push(...page[0].conversations"'!);
  }
  expect(pages).toEqual(expected);
  const reopened = await connect(`${base}?sessionId=${pages[1].sessionId}`);
  expect(reopened.frames[0]).toMatchObject({type: '"'connected', sessionId: 'b', resumed: true, entryCount: 1});
  expect(reopened.frames.filter(frame => frame.type === 'entry_upsert')).toEqual([
    {type: 'entry_upsert', index: 0, entry: store.get('b')"'!.entries[0]},
  ]);
  try {
    client.socket.send(JSON.stringify({type: '"'user_message', content: 'held turn'}));
    await running;
    const during = await client.ask({type: 'list_conversations'});
    expect(during).toEqual([{type: 'conversation_list', conversations: JSON.parse(JSON.stringify(store.listFor('owner')))}]);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    const closed = once(client.socket, 'close');
    client.socket.close();
    await closed;
    release();
  }
});

// spec: specs/hal-engine-websocket-protocol/spec.md#5.6
it('refuses unavailable history and sanitizes real store failures while keeping the socket usable', async () => {
  const inner = new RecordedStore();
  const driver = new MongoClient('mongodb://127.0.0.1:1/history-private');
  await driver.close();
  const collection = driver.db().collection('sessions') as unknown as CollectionLike<MongoSessionDocument>;
  const {findOne, updateOne, deleteOne, deleteMany, countDocuments} = collection;
  const withoutFind: CollectionLike<MongoSessionDocument> = {
    findOne: findOne.bind(collection), updateOne: updateOne.bind(collection),
    deleteOne: deleteOne.bind(collection), deleteMany: deleteMany.bind(collection),
    countDocuments: countDocuments.bind(collection),
  };
  const cannotList = new MongoSessionStore({collection: withoutFind});
  const failed = new MongoSessionStore({collection});
  const outcomes: Record<string, Frame[]> = {};
  for (const [name, history, store] of [
    ['default off', undefined, inner], ['explicit off', {enabled: false}, inner],
    ['no listFor', {enabled: true}, requiredMembers(inner)],
    ['no find', {enabled: true}, {...requiredMembers(inner), listFor: cannotList.listFor.bind(cannotList)}],
    ['closed database', {enabled: true}, {...requiredMembers(inner), listFor: failed.listFor.bind(failed)}],
  ] as const) {
    const client = await connect(await start(store, history));
    outcomes[name] = await client.ask({type: 'list_conversations'});
    expect(client.socket.readyState).toBe(WebSocket.OPEN);
  }
  expect(outcomes).toEqual(Object.fromEntries(Object.keys(outcomes).map(name => [name, [{
    type: 'error', code: name === 'closed database' ? 'SERVER_ERROR' : 'UNSUPPORTED', message: expect.any(String),
  }]])));
  expect(inner.calls).toEqual([]);
  expect(JSON.stringify(outcomes)).not.toMatch(/history-private|Mongo|topology|client must be connected/i);
  expect(logs.filter(line => line.level === 'error')).toEqual(expect.arrayContaining([
    expect.objectContaining({fields: expect.objectContaining({sessionId: expect.any(String)})}),
  ]));
  expect(JSON.stringify(logs)).not.toMatch(/acceptance-token|history-private|private content/);
});
